		const int KeptEntries = 4096;

		static Parser Recycled()
		{
			var spare = _spareParser;

			if (spare == null)
				return new Parser();

			_spareParser = null;

			return spare;
		}

		static void Recycle(Parser parser)
		{
			if (parser.Entries.Capacity <= KeptEntries)
				_spareParser = parser;
		}

